return {
  json: {
    error: {
      code: "INVALID_INPUT",
      message: "opportunity_id must be a non-empty string"
    }
  }
};

const rows = $input.all()
  .map(item => item.json);

const requestedId = $('When Executed by Another Workflow')
  .first()
  .json.opportunity_id.trim();

const opportunityRow = rows.find(
  row => row.opportunity_id
);

// Opportunity not found
if (!opportunityRow) {
  return [{
    json: {
      opportunity_id: requestedId,
      found: false,
      opportunity: null
    }
  }];
}

// Preserve nullable values and decimal precision
const solutionLines = rows
  .filter(row => row.solution_line_id)
  .map(row => ({
    solution_line_id: row.solution_line_id,
    product_id: row.product_id,
    sku: row.sku,
    product_name: row.product_name,
    product_role: row.product_role,
    commercial_status: row.commercial_status,
    quantity: row.quantity,
    estimated_unit_price_idr: row.estimated_unit_price_idr
  }));

// Format PostgreSQL DATE values as YYYY-MM-DD
const toDate = value =>
  value == null ? null : String(value).slice(0, 10);

return [{
  json: {
    opportunity_id: requestedId,
    found: true,
    opportunity: {
      opportunity_id: opportunityRow.opportunity_id,
      account_id: opportunityRow.account_id,
      owner_id: opportunityRow.owner_id,
      opportunity_name: opportunityRow.opportunity_name,
      stage: opportunityRow.stage,
      estimated_value_idr: opportunityRow.estimated_value_idr,
      expected_close_date: toDate(
        opportunityRow.expected_close_date
      ),
      target_deployment_date: toDate(
        opportunityRow.target_deployment_date
      ),
      customer_requirements:
        opportunityRow.customer_requirements_json,
      current_discount_pct:
        opportunityRow.current_discount_pct,
      requested_discount_pct:
        opportunityRow.requested_discount_pct,
      outstanding_questions:
        opportunityRow.outstanding_questions_json,
      solution_lines: solutionLines
    }
  }
}];
